-- Experiment modul – schema.sql
-- Defines the database schema for the Experiment module.
-- Loaded automatically by Docker on first startup via docker-entrypoint-initdb.d.
-- Tables use UUID primary keys generated by gen_random_uuid().

-- 1. Experiment template table
-- Stores the experiment definition (name, ethics approval, information text).
-- Once saved, an experiment cannot be modified — only soft deleted via deleted_at.
CREATE TABLE experiments (
    id                     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name                   VARCHAR(255) NOT NULL,
    ethics_approval_number VARCHAR(100) NOT NULL,  -- Used as group_ref in the Participant and Questionnaire modules
    information_text       TEXT,
    created_at             TIMESTAMP NOT NULL DEFAULT NOW(),
    deleted_at             TIMESTAMP DEFAULT NULL   -- NULL if not deleted; soft delete only
);

-- 2. Questionnaires linked to an experiment template
-- Stores the ordered list of questionnaires for each experiment.
-- The version is locked at the time the experiment is saved.
-- Composite primary key prevents the same questionnaire from being added twice.
CREATE TABLE experiment_questionnaires (
    experiment_id    UUID NOT NULL REFERENCES experiments(id),
    questionnaire_id VARCHAR(100) NOT NULL,
    version          VARCHAR(50) NOT NULL,
    occasion         VARCHAR(20) NOT NULL CHECK (occasion IN ('pre', 'post', 'between_cycles')),
    position         INTEGER NOT NULL,
    PRIMARY KEY (experiment_id, questionnaire_id)
);

-- 3. Session table (experiment run)
-- Each row represents one participant running one experiment.
-- participant_pseudonym is unique across all sessions and links data across all three modules.
CREATE TABLE sessions (
    id                          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    experiment_id               UUID NOT NULL REFERENCES experiments(id),
    participant_pseudonym        VARCHAR(255) NOT NULL UNIQUE,  -- Unique identifier shared across modules
    language                    VARCHAR(5) NOT NULL CHECK (language IN ('hu', 'en')),
    paper_consent_confirmed_at  TIMESTAMP DEFAULT NULL,         -- Set when the participant confirms paper consent
    demographics_id             VARCHAR(100) DEFAULT NULL,      -- ID received from the Participant module
    status                      VARCHAR(20) NOT NULL DEFAULT 'in_progress'
                                    CHECK (status IN ('in_progress', 'completed')),
    started_at                  TIMESTAMP NOT NULL DEFAULT NOW(),
    ended_at                    TIMESTAMP DEFAULT NULL           -- Set when the session is completed
);

-- 4. Questionnaire responses linked to a session
-- Each row records one completed questionnaire response for a session.
-- response_id is received from the Questionnaire module.
-- Composite primary key prevents duplicate responses for the same questionnaire in one session.
CREATE TABLE session_responses (
    session_id       UUID NOT NULL REFERENCES sessions(id),
    questionnaire_id VARCHAR(100) NOT NULL,
    response_id      VARCHAR(100) NOT NULL,
    PRIMARY KEY (session_id, questionnaire_id)
);